function riskFlags(best, platform, region, edition, prefs) {
  const flags = [];
  if (!best.channel.physical && prefs.wantsCancel) {
    flags.push({
      title: "İade penceren çıkışta değil, ön yüklemede kapanır",
      body: `${platform.label} üzerinde dijital ön sipariş, indirme başladığı anda iade edilemez hale gelir, çıkıştan kabaca ${platform.preloadLeadDays} gün önce. Kilidi açıldığında oynamaktansa vazgeçme seçeneğini korumak daha önemliyse ön yüklemeyi başlatma.`,
      severity: "high"
    });
  }
  if (best.channel.id === "retailer-code" && prefs.wantsPreload) {
    flags.push({
      title: "Geç bir kod ön yüklemene mal olabilir",
      body: "Perakendeci dijital kodları genellikle çıkıştan 24 ila 72 saat önce teslim edilir. Bu, Xbox'ta ön yükleme penceresinin içindedir ve PlayStation'da dar olabilir, bu yüzden çıkış günü indiriyor olabilirsin.",
      severity: "medium"
    });
  }
  if (best.channel.physical) {
    flags.push({
      title: "Diskler yine de ilk gün yaması indirir",
      body: "Disk temel indirmeyi kaldırır ama çıkış yamasını kaldırmaz. Bant genişliğini yine de planla ve oynamadan önce bir süre kurulum bekle.",
      severity: "medium"
    });
  }
  if (best.channel.id === "marketplace-key") {
    flags.push({
      title: "Gri pazar anahtarları iptal riski taşır",
      body: "İptal edilen anahtar genellikle oyun yok ve iade yok demektir ve yayıncı desteği satmadığı bir hak konusunda müdahale etmez. Tasarruf, çıkış günü oyununda riske nadiren değer.",
      severity: "high"
    });
  }
  if (edition.id !== "standard") {
    flags.push({
      title: `${edition.label} bonusları satın alan hesaba kilitlenir`,
      body: `${edition.note} Siparişten sonra kanal veya platform değiştirmek, bonus yığınını yeniden satın almak demektir, bu yüzden sürümden önce platforma karar ver.`,
      severity: "low"
    });
  }
  if (region.consumerLaw >= 8 && !best.channel.physical) {
    flags.push({
      title: "Yasal iptal hakkın var, indirmeden önce kullan",
      body: `${region.note} Bu hak genellikle yalnızca dijital içerik indirilmediği sürece sürer, bu da mağazanın uyguladığı sınırla aynıdır.`,
      severity: "low"
    });
  }
  return flags;
}
export function rankChannels(input) {
  const platform = platformById(input.platform) ?? PLATFORMS[0];
  const region = regionById(input.region) ?? REGIONS[0];
  const edition = editionById(input.edition) ?? EDITIONS[0];
  const prefs = input.prefs;
  const weights = weightsFor(prefs);
  const ranked = CHANNELS.filter((c) => c.platforms.includes(platform.id)).map((channel) => {
    const adj = adjustedAxes(channel, platform, region, edition);
    const axes = Object.keys(AXIS_LABELS).map((id) => ({
      id,
      label: AXIS_LABELS[id],
      raw: adj[id],
      weight: weights[id],
      detail: AXIS_DETAIL[id]
    }));
    const score = Math.round(axes.reduce((sum, a) => sum + a.raw / 10 * a.weight, 0) * 10) / 10;
    const sorted = [...axes].sort((a, b) => b.raw - a.raw);
    return {
      channel,
      score,
      axes,
      strengths: sorted.slice(0, 2).filter((a) => a.raw >= 6).map((a) => a.label),
      risks: sorted.slice(-2).filter((a) => a.raw <= 4).map((a) => a.label),
      confidence: channel.confidence
    };
  }).sort((a, b) => b.score - a.score || a.channel.label.localeCompare(b.channel.label));
  const best = ranked[0];
  const runnerUp = ranked[1];
  const wanted = [
    prefs.wantsPreload ? "kilidi açıldığı anda oynamak" : null,
    prefs.wantsCancel ? "iptal seçeneğini korumak" : null,
    prefs.wantsResale ? "yeniden satış veya ödünç değeri" : null
  ].filter(Boolean);
  const priorities = wanted.length === 0 ? "değerin ötesinde güçlü bir tercih yok" : wanted.length === 1 ? wanted[0] : `${wanted.slice(0, -1).join(", ")} ve ${wanted.at(-1)}`;
  const headline = `${platform.label} üzerinde ${best.channel.short}`;
  const reason = `Bize ${priorities} konusunun önemli olduğunu söylediğin için ${best.channel.label.toLowerCase()}, ${region.label} bölgesinde ${edition.label} siparişi için 100 üzerinden ${best.score} alıyor ve ${best.strengths.join(" ve ").toLowerCase() || "genel denge"} konusunda önde${runnerUp ? `, ${runnerUp.channel.short.toLowerCase()} ${runnerUp.score} puanla geride` : ""}.`;
  return {
    platform,
    region,
    edition,
    prefs,
    weights,
    ranked,
    best,
    runnerUp,
    headline,
    reason,
    riskFlags: riskFlags(best, platform, region, edition, prefs),
    timeline: timeline(platform, region)
  };
}
